<?php
declare(strict_types=1);
require_once __DIR__.'/../config/bootstrap.php';$admin=require_permission($pdo,'site.manage');$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    require_csrf();
    try{
        $action=post_string('action');$pdo->beginTransaction();settings_assert_admin($pdo,(int)$admin['id']);
        if($action==='country'){
            $country=geo_country(post_string('country_code',2));$active=post_string('is_active');if(!in_array($active,['0','1'],true))throw new InvalidArgumentException('Bitte einen gültigen Status wählen.');
            $q=$pdo->prepare('SELECT code FROM market_countries WHERE code=? FOR UPDATE');$q->execute([$country]);if(!$q->fetchColumn())throw new InvalidArgumentException('Land nicht vorhanden.');
            $pdo->prepare('UPDATE market_countries SET is_active=? WHERE code=?')->execute([(int)$active,$country]);audit_log($pdo,(int)$admin['id'],'geography.country_changed',null,['country'=>$country,'active'=>(int)$active]);
        }elseif($action==='source'){
            $id=filter_var($_POST['import_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$active=post_string('is_active');if(!$id||!in_array($active,['0','1'],true))throw new InvalidArgumentException('Ungültiger Datenimport.');
            $q=$pdo->prepare('SELECT id FROM geo_imports WHERE id=? FOR UPDATE');$q->execute([$id]);if(!$q->fetchColumn())throw new InvalidArgumentException('Datenimport nicht gefunden.');$pdo->prepare('UPDATE geo_imports SET is_active=? WHERE id=?')->execute([(int)$active,$id]);audit_log($pdo,(int)$admin['id'],'geography.source_changed',$id,['active'=>(int)$active]);
        }elseif($action==='translation'){
            $locale=post_string('locale',8);$key=post_string('setting_key',100);$text=trim(post_string('content',2000));
            if(!isset(i18n_locales()[$locale])||$locale==='de'||!in_array($key,['tagline','hero_title','hero_text'],true)||!preg_match('//u',$text)||preg_match('/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/u',$text))throw new InvalidArgumentException('Bitte eine gültige Sprache und reinen Text wählen.');
            $max=$key==='hero_text'?500:120;if(mb_strlen($text)>$max)throw new InvalidArgumentException('Die Übersetzung ist zu lang.');
            $pdo->prepare('INSERT INTO market_content_translations(setting_key,locale,content,updated_by) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE content=VALUES(content),updated_by=VALUES(updated_by)')->execute([$key,$locale,$text,$admin['id']]);audit_log($pdo,(int)$admin['id'],'geography.content_translated',null,['key'=>$key,'locale'=>$locale]);
        }elseif($action==='category_translation'){
            $locale=post_string('locale',8);$id=filter_var($_POST['category_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$name=trim(post_string('name',400));
            if(!$id||!isset(i18n_locales()[$locale])||$locale==='de'||!preg_match('/\A.{1,100}\z/us',$name)||preg_match('/[\x00-\x1f\x7f]/u',$name)||!catalog_text_allowed($name))throw new InvalidArgumentException('Bitte Kategorie, Sprache und Namen prüfen.');
            $q=$pdo->prepare('SELECT id FROM market_categories WHERE id=?');$q->execute([$id]);if(!$q->fetchColumn())throw new InvalidArgumentException('Kategorie nicht gefunden.');
            $pdo->prepare('INSERT INTO market_category_translations(category_id,locale,name,updated_by) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),updated_by=VALUES(updated_by)')->execute([$id,$locale,$name,$admin['id']]);audit_log($pdo,(int)$admin['id'],'geography.category_translated',$id,['locale'=>$locale]);
        }else throw new InvalidArgumentException('Ungültige Aktion.');
        $pdo->commit();redirect('/admin/geography.php?saved=1');
    }catch(InvalidArgumentException $e){if($pdo->inTransaction())$pdo->rollBack();http_response_code(422);$error=$e->getMessage();}
    catch(Throwable){if($pdo->inTransaction())$pdo->rollBack();http_response_code(503);$error='Die Änderung konnte nicht gespeichert werden.';}
}
$countries=$pdo->query('SELECT c.code,c.is_active,(SELECT COUNT(*) FROM geo_locations p JOIN geo_imports i ON i.id=p.import_id WHERE p.country_code=c.code AND i.is_active=1 AND i.license_reviewed=1) AS locations FROM market_countries c ORDER BY c.code')->fetchAll();
$imports=$pdo->query('SELECT * FROM geo_imports ORDER BY id DESC LIMIT 50')->fetchAll();$categories=catalog_categories($pdo,false);$translations=$pdo->query('SELECT setting_key,locale,content FROM market_content_translations ORDER BY locale,setting_key')->fetchAll();
$pageTitle='Länder, Sprachen & Standortdaten';include __DIR__.'/../includes/header.php';
?>
<main class="container admin-page"><div class="page-heading"><p class="eyebrow">Internationale Märkte</p><h1>Länder, Sprachen und Standortdaten.</h1><p>Ein Ländermarkt besitzt eigene Angebote und Werbeplätze. Internationale Suche verbindet die aktiven Märkte; Werbung bleibt dem ausgewählten Markt zugeordnet.</p></div><div class="admin-layout"><?php include __DIR__.'/../includes/admin-nav.php';?><div class="admin-content">
<?php if($error):?><p class="notice error" role="alert"><?=h($error)?></p><?php endif;?><?php if(($_GET['saved']??'')==='1'):?><p class="notice success">Änderung gespeichert.</p><?php endif;?>
<section class="panel"><h2>Aktive Ländermärkte</h2><p>Das Deaktivieren verbirgt Angebote und verhindert neue Transaktionen. Bestehende Gebote werden nicht gelöscht; fällige Konflikte benötigen manuelle Prüfung.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Land</th><th>Freigegebene PLZ-Punkte</th><th>Marktstatus</th></tr></thead><tbody><?php foreach($countries as $country):?><tr><td><?=h(geo_countries()[$country['code']]??$country['code'])?> (<?=h($country['code'])?>)</td><td><?=(int)$country['locations']?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="country"><input type="hidden" name="country_code" value="<?=h($country['code'])?>"><select name="is_active" aria-label="Marktstatus"><option value="1" <?=$country['is_active']?'selected':''?>>Aktiv</option><option value="0" <?=!$country['is_active']?'selected':''?>>Inaktiv</option></select><button class="button secondary" type="submit">Speichern</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><h2>Lokale PLZ-Daten</h2><p>Ohne freigegebene Koordinaten gibt es keine erfundene Entfernung. CSV-Import erfolgt lokal über <code>ops/import-postcodes.php</code> mit Quelle, Lizenznotiz und ausdrücklicher Rechtebestätigung. Die Nutzungsrechte von <code>ZIP/PLZ.csv</code> sind nicht geklärt; der Bestand wird deshalb nicht automatisch produktiv importiert.</p><p>Details und Format: <code>docs/INTERNATIONAL.md</code>. Kein externer Kartendienst erforderlich.</p><?php foreach($imports as $source):?><details><summary><?=h($source['country_code'].' · '.$source['source_name'])?> · <?=(int)$source['record_count']?> Punkte</summary><p><?=h($source['license_note'])?></p><p>SHA-256: <?=h($source['source_sha256'])?></p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="source"><input type="hidden" name="import_id" value="<?=(int)$source['id']?>"><input type="hidden" name="is_active" value="<?=$source['is_active']?'0':'1'?>"><button class="button secondary" type="submit"><?=$source['is_active']?'Datenquelle deaktivieren':'Datenquelle aktivieren'?></button></form></details><?php endforeach;?></section>
<section class="panel"><h2>Übersetzte Markentexte</h2><p>Eigene deutsche Texte werden nicht automatisch übersetzt. Hier erhält jede Sprache ihre geprüfte Fassung; leere Werte verwenden den Ausgangstext.</p><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="translation"><label class="field">Sprache<select name="locale"><?php foreach(i18n_locales() as $code=>$label)if($code!=='de'):?><option value="<?=h($code)?>"><?=h($label)?></option><?php endif;?></select></label><label class="field">Text<select name="setting_key"><option value="tagline">Markenclaim</option><option value="hero_title">Startseitentitel</option><option value="hero_text">Startseitentext</option></select></label><label class="field">Übersetzung<textarea name="content" maxlength="500"></textarea></label><button class="button" type="submit">Übersetzung speichern</button></form><?php foreach($translations as $translation):?><p><strong><?=h($translation['locale'].' · '.$translation['setting_key'])?></strong>: <?=h($translation['content'])?></p><?php endforeach;?></section>
<section class="panel"><h2>Kategorien übersetzen</h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="category_translation"><label class="field">Kategorie<select name="category_id"><?php foreach($categories as $category):?><option value="<?=(int)$category['id']?>"><?=h($category['name'])?></option><?php endforeach;?></select></label><label class="field">Sprache<select name="locale"><?php foreach(i18n_locales() as $code=>$label)if($code!=='de'):?><option value="<?=h($code)?>"><?=h($label)?></option><?php endif;?></select></label><label class="field">Übersetzter Name<input name="name" maxlength="100" required></label><button class="button" type="submit">Kategorietext speichern</button></form></section>
</div></div></main><?php include __DIR__.'/../includes/footer.php';?>
